const branchRows=Array.from({length:8},(_,i)=>{
  const list=actions.filter(a=>a.roundId===i+1);return{round:i+1,actionFamilies:list.length,none:list.filter(a=>a.target==="none").length,fixedAlpha:list.filter(a=>a.target==="fixed_alpha").length,required:list.filter(a=>a.target==="required").length,maxActionTargetPairs:list.reduce((n,a)=>n+(a.target==="required"?4:1),0),resourceDependentRule:"both budgets sufficient",statusDependentRule:"delivered excluded as target; compromised legal; fixed-alpha requires active alpha"};
});
const naive=branchRows.reduce((n,r)=>n*BigInt(r.maxActionTargetPairs),1n);
const dp=new Map<string,bigint>();
function resourceUpper(round:number,isr:number,support:number):bigint{
  if(round===9)return 1n;const key=`${round}/${isr}/${support}`;if(dp.has(key))return dp.get(key)!;
  let result=0n;for(const a of actions.filter(a=>a.roundId===round))if(a.isrCost<=isr&&a.supportCost<=support)result+=BigInt(a.target==="required"?4:1)*resourceUpper(round+1,isr-a.isrCost,support-a.supportCost);
  dp.set(key,result);return result;
}
const resourceBound=resourceUpper(1,100,100);
const costBounds=branchRows.map((r:any)=>({round:r.round,maxCumulativeIsr:Array.from({length:r.round},(_,i)=>Math.max(...actions.filter(a=>a.roundId===i+1).map(a=>a.isrCost))).reduce((a,b)=>a+b,0),maxCumulativeSupport:Array.from({length:r.round},(_,i)=>Math.max(...actions.filter(a=>a.roundId===i+1).map(a=>a.supportCost))).reduce((a,b)=>a+b,0)}));
assert.equal(resourceBound,naive,"With current 100/100 costs, affordability alone never prunes a normal-start sequence");
csv("scenario5-resource-cost-bounds-current.csv",costBounds);
const distribution=Object.fromEntries(Object.keys(C.SCENARIO5_END_STATE_LABELS_FA).map(id=>[id,runs.filter(r=>r.result.missionEndState.endStateId===id).length]));

// Complete post-run cognitive field inventory, including metadata and all four phase elements.
function leaves(value:any,prefix:string):[string,any][]{if(value===null||typeof value!=="object")return[[prefix,value]];return Object.entries(value).flatMap(([k,v])=>leaves(v,`${prefix}.${k}`));}
const cognitiveLeaves=leaves(runs[0].result.cognitive,"result.cognitive");
const readiness=cognitiveLeaves.map(([field,value])=>{
  const key=field.split(".").at(-1)!;const meta=!/dataCompleteness|orientation|constructs|telemetrySummary/.test(field);
  const discipline=field.endsWith("informationDiscipline"),risk=field.endsWith("riskPosture"),osi=field.endsWith("orientation.overall")||field.includes("phaseScores"),ms=/DecisionMs/.test(field),count=/totalRevisions|revisedWindows/.test(field);
  const nullRule=discipline?"always null; not measured":field.includes("dataCompleteness")?"never null; ratios of valid expected telemetry":meta?"not null in valid runtime result":field.endsWith("evidenceResponsiveUpdating")?"null if no valid successive checkpoint pair has changed visible-evidence support":field.endsWith("decisionCoherence")?"null if fewer than two usable reason/coherence phases":field.endsWith("resourceStewardship")?"null unless all 8 decisions have before/after resources and diagnostic profiles":field.endsWith("orientation.overall")?"null unless every A/B/C/D phase score exists":field.includes("phaseScores")?"null for phase without eligible orientation windows":field.endsWith("integration")?"null if either strength missing or sum is zero":field.endsWith("dispersion")?"null with fewer than two phase scores":ms?"null if no finite active times":count?"non-null count":field.endsWith("evidenceTriggeredRevisionRate")?"null if no decision has evidence opened between first selection and confirmation":"null if no eligible/diagnostic windows for this proxy";
  return {exactResultField:field,scale:meta?"identifier/version/status string":discipline?"null":osi||risk?"-1..1 relative index":ms?"nonnegative wall ms":count?(key==="revisedWindows"?"0..8":"nonnegative count"):field.endsWith("dispersion")?"0..1 population SD over phase OSI":"0..100 proxy/percent",nullBehavior:nullRule,currentAarVisibility:meta?"not directly rendered; caveat prose remains":discipline?"not measured text":field.includes("phaseScores")?"AAR phase loop":field.includes("constructs")?"AAR construct cards":"AAR numeric text",suitableForScenario5CognitiveDashboard:meta?"conditional: metadata/audit only":discipline?"no: unmeasured":risk?"conditional: non-normative axis":"conditional: completeness/validity/context required",futureCrossScenario:meta||discipline?"no":"candidate",caveat:meta?"Versions/validity must travel with any exported result":risk?"Relative exposure among available options; positive/negative is not good/bad":field.includes("dataCompleteness.evidence")?"Reference validity coverage, not amount of evidence engagement":"Scenario-conditioned behavioral proxy; human/psychometric validation is not claimed; do not aggregate into a global Cognitive Score"};
});
csv("scenario5-cognitive-output-fields-current.csv",readiness);
const readyText=`# Current cognitive-dashboard readiness — extraction only\n\nNo dashboard is implemented. This inventory covers every leaf of the current Scenario5CognitiveRunResult interface as instantiated in a complete current run, including all four phase scores.\n\n${table(readiness)}\n## 1 Data completeness\nThe six fields are current valid-record percentages, not ability measures. Overall = .50 decisions + .15 timing + .15 evidence-reference integrity + .10 estimates + .10 reasons. Evidence completeness can be 100 with no evidence opened.\n\n## 2 OSI overall and phase\nOption orientation is (strategicLoading-operationalLoading)/(sum+1e-9), centered and maximum-absolute-normalized within the actually available action set. A2 is excluded from OSI. Phase means are A/B/C/D; overall requires all four.\n\n## 3 Operational/Strategic Strength\nAbsolute operationalLoading and strategicLoading are phase-balanced and ×100, separate from centered OSI.\n\n## 4 Integration/Dispersion\nIntegration is 2*O*S/(O+S), null for missing/zero denominator. Dispersion is the population SD of available phase OSI, null below two phases. They are not a general decision-quality score.\n\n## 5 Canonical cognitive constructs\nThe eleven keys in the field table are the exact current construct set. Information Discipline is ALWAYS null/not measured. Risk Posture is -1..1, relative and non-normative. MultiDomainIntegration uses existing nine-domain salience entropy; it is not the orientation harmonic-integration field.\n\n## 6 Decision timing/revisions\nRuntime raw input: decisions[].enteredAtMs/confirmedAtMs/elapsedMs/activeDecisionMs/hiddenTabMs/revisionCount/selectionHistory. Current result exposes median/IQR active milliseconds, total revisions, revised windows and evidence-triggered revision rate. R4/R6/R8 reason time is outside the confirmed decision timing. Repeated same-action clicks do not add a revision. Synthetic calibration driver timestamps must not be interpreted as human timing.\n\n## 7 Evidence-use behavior\nRuntime evidence[], evidenceOpens[].windowId/openedAtMs/closedAtMs/activeDwellMs, decisions[].availableEvidenceIds/openedEvidenceIds are available post-run. Explicit detail opens only count. InformationSeeking combines existing option loading plus relevant evidence coverage/diversity, not mission correctness. The aggregate result does not expose total evidence dwell or opened-source entropy separately. Current AAR shows per-item opened/not-opened.\n\n## 8 Belief/updating behavior\nFour runtime beliefs have checkpointId, recordedAtMs, mostLikelyCorridorId, corridorConfidence, targetedInterferenceEstimate, targetedInterferenceConfidence, visibleEvidenceIdsAtCheckpoint. All are available for later context-specific plots; the current cognitive result exposes evidenceResponsiveUpdating, based only on targeted-estimate changes versus visible-evidence support changes. Corridor correctness belongs to domain output, not cognitive correctness points. Reasons expose phaseId/reasonId/recordedAtMs/capturedBeforeOutcome; current decision coherence uses the existing frozen reason-alignment/cross-decision matrices.\n\n## 9 Mission/domain outputs must remain separate\nmissionEndState; domain.gnssPntAssessment/navigationIntegrity/criticalDelivery/logisticsResilience/delayControl/civilianImpactProxy/networkLogisticsBalance are descriptive mission/domain outputs. Neither outcome nor winning generates cognitive points. Domain checkpoints may compare beliefs to truth only after completion. Domain exposure and Actor delay decomposition must not be relabelled cognitive ability.\n\n## 10 Hidden/audit-only fields\nworldId, seed, true primary corridor, Actor profile/objective/internal posture, hidden provenance and Actor delay decomposition are research/AAR context, not live player evidence. Metadata version/validity fields are audit context, not a score.\n\n## 11 No global Cognitive Score\nNo sum/average of OSI, integration, constructs, completeness or mission success is defined. Risk Posture is non-normative. Unmeasured Information Discipline cannot be assigned zero or inferred from other measures. No human, psychometric, intelligence, personality or cross-person validity is claimed.\n\n## 12 Candidate cross-scenario constructs and data requirements\nActive product Scenario 1 is internal Scenario 4 (App released mapping id4), not legacy id1. Its Cognitive V3 input requires records, telemetry, attribution estimates, move reasons and resourceEvents; outputs have three per-move orientation scores, response-process flags, per-window audits and timing dwell in addition to shared-looking constructs. S5 requires eight decisions, four corridor/targeted beliefs, B/C/D reasons, visible-evidence/open telemetry and resource snapshots. Scenario-4 has coalitionOrientation and a measured informationDiscipline path; S5 has no coalition construct and informationDiscipline is null. Similar names are candidates only: available-option normalization, task windows, evidence schemas, phase weights, expert versions and null rules differ. No cross-scenario dashboard, harmonization formula or Scenario-1 change is made.\n\nSource: scenario-five/model/cognitive/types.ts, cognitiveEngine.ts, evidenceScoring.ts, reasonModel.ts; runtime/telemetryAdapter.ts and domainMetrics.ts; ScenarioFiveSummary.tsx; scenario-four/model/cognitiveEngineV3.ts CognitiveModelV3Input/Result.\n`;
write("scenario5-cognitive-dashboard-readiness.md",readyText);

// Coverage-oriented selection: eight policy families, all Actor profiles/corridors, distinct available end states.
const selected:any[]=[];const seen={policies:new Set<string>(),actors:new Set<string>(),corridors:new Set<string>(),ends:new Set<string>()};
while(selected.length<8){
  const candidates=runs.filter(r=>!seen.policies.has(r.policyId));
  candidates.sort((a,b)=>{
    const score=(r:any)=>Number(!seen.actors.has(r.world.actorProfileId))+Number(!seen.corridors.has(r.world.primaryAffectedCorridorId))+Number(!seen.ends.has(r.result.missionEndState.endStateId));
    return score(b)-score(a)||a.traceId.localeCompare(b.traceId);
  });
  const r=candidates[0];selected.push(r);seen.policies.add(r.policyId);seen.actors.add(r.world.actorProfileId);seen.corridors.add(r.world.primaryAffectedCorridorId);seen.ends.add(r.result.missionEndState.endStateId);
}
assert.equal(seen.actors.size,4);assert.equal(seen.corridors.size,4);assert.equal(seen.ends.size,Object.values(distribution).filter(n=>Number(n)>0).length);
const convoyCompact=(s:any)=>["alpha","beta","gamma","delta"].map(id=>`${id}: ${s[id+"Status"]}, I=${s[id+"Integrity"]}, delay=${s[id+"Delay"]}, ETA=T+${s[id+"ETA"]}`).join("; ");
let pathsText="# Representative current paths — actual extracted traces\n\nResearch document: world/profile/primary fields below were HIDDEN during play. All environment seeds are 1; M10 uses current missionEffectivePolicySeed(worldIndex,1,1001). Timings/beliefs/reasons are those of existing calibration policies, not human behavior. No oracle/stress policy was used. Only three end-state IDs occur in this requested seed-1 corpus; no unobserved end state is fabricated.\n\n"+table(selected.map(r=>({traceId:r.traceId,policy:r.policyId,hiddenActor:r.world.actorProfileId,hiddenPrimary:r.world.primaryAffectedCorridorId,endState:r.result.missionEndState.endStateId})))+"\n";
for(const run of selected){
  pathsText+=`## ${run.traceId} — ${run.policyId}\n\n`;
  for(let round=1;round<=8;round++){
    const before=run.stages.find((s:any)=>s.round===round&&s.runtimeStageId.startsWith("decision:"));const after=run.stages.find((s:any)=>s.round===round&&s.runtimeStageId==="outcome_review");
    const oldIds=new Set(before.visibleEvidenceIds);const fresh=run.evidence.filter((e:any)=>after.visibleEvidenceIds.includes(e.evidenceId)&&!oldIds.has(e.evidenceId));
    pathsText+=`### R${round}: ${C.SCENARIO5_ROUND_CONTENT_FA[round].title}\n\n`;
    pathsText+=`- Prompt: «${C.SCENARIO5_ROUND_CONTENT_FA[round].problem}»\n- Before: T+${before.clockAfter}; ISR ${before.isrAfter}; support ${before.supportAfter}; ${before.visibleEvidenceCount} visible evidence. ${convoyCompact(before)}.\n- Selected: «${actionName(after.selectedAction)}» (${after.selectedAction}); target ${after.selectedTarget?convoyName(after.selectedTarget):"none"}.\n- Visible consequence: T+${after.clockBefore}→T+${after.clockAfter}; ISR ${after.isrBefore}→${after.isrAfter}; support ${after.supportBefore}→${after.supportAfter}. ${convoyCompact(after)}.\n- Fresh information: ${fresh.length}; ${fresh.length?fresh.map(evidenceSummary).join("؛ "):"شاهد تازه‌ای به تصویر عملیاتی اضافه نشد."}\n- Next screen after outcome: ${after.nextStage}. ${[4,6,8].includes(round)?"This outcome was preceded by the existing reason gate.":""}\n\n`;
  }
  pathsText+=`Final mission result: «${C.SCENARIO5_END_STATE_LABELS_FA[run.result.missionEndState.endStateId]}»; continuity ${run.result.domain.logisticsResilience.networkContinuityPercent}%; alpha integrity ${run.result.domain.criticalDelivery.integrity}; alpha ETA ${run.result.domain.criticalDelivery.projectedArrivalMinute}; deadline ${run.result.domain.criticalDelivery.deadlineMinute}.\n\nExact current final cognitive output:\n\n\`\`\`json\n${JSON.stringify(run.result.cognitive,null,2)}\n\`\`\`\n\nHidden during play: ${run.world.worldId}, ${run.world.actorProfileId}, true primary ${run.world.primaryAffectedCorridorId}, environment seed 1, evidence provenance and Actor reaction decomposition. Details/counts in current-path-traces.csv are stage-entry snapshots; decision-row selectedAction is the policy's next submitted selection, not a UI default.\n\n`;
}
write("scenario5-representative-paths.md",pathsText);

